"""Migrated opportunity_pipeline workflow from Meridian CRM 4.2."""

from typing import Any


def _numeric_value(value: Any) -> float:
    """Apply the relevant VRL numeric coercion rules."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _has_positive_amount(record: dict) -> bool:
    return _numeric_value(record.get("AMT", "")) > 0


def _has_close_date(record: dict) -> bool:
    # The source guard is: CLOSE_DT <> '00000000'.
    return str(record.get("CLOSE_DT", "")) != "00000000"


def _has_loss_reason(record: dict) -> bool:
    # The source guard is: LOST_RSN <> ''.
    return isinstance(record.get("LOST_RSN", ""), str) and record.get("LOST_RSN", "") != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity pipeline transition."""
    result_record = dict(record)

    transitions = (
        ("P", "qualify", "Q", _has_positive_amount, (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
        ("Q", "advance", "N", None, (("set", "STAGE_PCT", "60"),)),
        (
            "N",
            "close_won",
            "W",
            _has_close_date,
            (
                ("set", "STAGE_PCT", "100"),
                ("audit", "OPP_WON"),
                ("notify", "won_deal"),
            ),
        ),
        ("P", "close_lost", "L", _has_loss_reason, (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("Q", "close_lost", "L", _has_loss_reason, (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("N", "close_lost", "L", _has_loss_reason, (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
    )

    for from_state, transition_event, to_state, guard, actions in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        audits = []
        notifies = []
        for action in actions:
            kind = action[0]
            if kind == "set":
                result_record[action[1]] = action[2]
            elif kind == "audit":
                audits.append(action[1])
            elif kind == "notify":
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
